local OutputBytes = {}
local DynamicKey = 187

-- Safe bitwise XOR function compatible with all Luau environments
local function safeXor(n1, n2)
    local res = 0
    for i = 0, 31 do
        local b1 = (n1 / 2^i) % 2 >= 1 and 1 or 0
        local b2 = (n2 / 2^i) % 2 >= 1 and 1 or 0
        if b1 ~= b2 then
            res = res + 2^i
        end
    end
    return res
end

-- Multi-stage decryption loop
for idx = 1, #ByteTable do
    local scrambledVal = ByteTable[idx]
    local charCode = safeXor(scrambledVal - 13, DynamicKey)
    OutputBytes[idx] = string.char(charCode)
end

